class Solution {
  public String similarRGB(String color) {
    StringBuilder sb = new StringBuilder("#");
    for (int i = 1; i < 7; i += 2) {
      int v = Integer.parseInt(color.substring(i, i + 2), 16);
      int q = (v + 8) / 17; // nearest multiple of 0x11
      sb.append(String.format("%02x", q * 17));
    }
    return sb.toString();
  }
}
